import numpy as np
from collections import Counter

exp_info = np.load('/app/data/beh/Imaging_Exp_info.npy', allow_pickle=True).item()

# Get all unique stimulus names across all sessions
all_stim = set()
for exp_type in exp_info:
    beh_file = f'/app/data/beh/Beh_{exp_type}.npy'
    try:
        beh = np.load(beh_file, allow_pickle=True).item()
        for k, sess in beh.items():
            if 'UniqWalls' in sess:
                for w in sess['UniqWalls']:
                    all_stim.add(w)
    except:
        pass

print('All unique stimulus names:', sorted(all_stim))

# Check how many sessions have each stimulus
stim_counts = Counter()
for exp_type in exp_info:
    beh_file = f'/app/data/beh/Beh_{exp_type}.npy'
    try:
        beh = np.load(beh_file, allow_pickle=True).item()
        for k, sess in beh.items():
            if 'UniqWalls' in sess:
                for w in sess['UniqWalls']:
                    stim_counts[w] += 1
    except:
        pass

print('\nStimulus counts (across all beh file entries):')
for s, c in sorted(stim_counts.items()):
    print(f'  {s}: {c}')
